//! R10 depth closure: native parser+Owner with Binance depth20 and OKX books5. No trading.
use futures_util::{SinkExt,StreamExt};use serde_json::json;use spotarb_native_market_core::{owner_index,HistorySink,CoreError,Owner,RawFrame,Update,Venue};use std::{collections::HashSet,time::{Duration,Instant,SystemTime,UNIX_EPOCH}};use tokio_tungstenite::{connect_async,tungstenite::Message};
struct H{n:u64}impl HistorySink for H{fn accept(&mut self,_:&RawFrame,_:&Update)->Result<(),CoreError>{self.n+=1;Ok(())}}fn wall()->i64{SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_millis()as i64}
#[tokio::main]async fn main(){let bases=std::env::var("R10_BASES").unwrap().split(',').map(str::to_string).collect::<Vec<_>>();let secs=std::env::var("R10_SECONDS").ok().and_then(|s|s.parse().ok()).unwrap_or(60);let start=Instant::now();let mut owners=(0..12).map(|i|Owner::new(i,12,800).unwrap()).collect::<Vec<_>>();let mut h=H{n:0};let(mut sb,mut so)=(HashSet::new(),HashSet::new());let mut errors=0u64;let streams=bases.iter().map(|x|format!("{}usdt@depth20@100ms",x.to_lowercase())).collect::<Vec<_>>().join("/");let(mut b,_)=connect_async(format!("wss://fstream.binance.com/stream?streams={streams}")).await.unwrap();let(mut o,_)=connect_async("wss://ws.okx.com:8443/ws/v5/public").await.unwrap();let args=bases.iter().map(|x|json!({"channel":"books5","instId":format!("{x}-USDT")})).collect::<Vec<_>>();o.send(Message::Text(json!({"op":"subscribe","args":args}).to_string())).await.unwrap();while start.elapsed()<Duration::from_secs(secs){tokio::select!{x=b.next()=>if let Some(Ok(Message::Text(raw)))=x{let f=RawFrame{source:None,venue:Venue::BinanceFutures,epoch:1,received_ns:start.elapsed().as_nanos()as u64,received_wall_ms:wall(),raw};match spotarb_native_market_core::parse(&f){Ok(u)=>{sb.insert(u.base.clone());let i=owner_index(&u.base,12);if owners[i].ingest_parsed(&f,u,&mut h).is_err(){errors+=1}},Err(_)=>errors+=1}},x=o.next()=>if let Some(Ok(Message::Text(raw)))=x{if raw.contains("\"event\""){continue}let f=RawFrame{source:None,venue:Venue::OkxSpot,epoch:1,received_ns:start.elapsed().as_nanos()as u64,received_wall_ms:wall(),raw};match spotarb_native_market_core::parse(&f){Ok(u)=>{so.insert(u.base.clone());let i=owner_index(&u.base,12);if owners[i].ingest_parsed(&f,u,&mut h).is_err(){errors+=1}},Err(_)=>errors+=1}}}}let now=start.elapsed().as_nanos()as u64;let(mut paired,mut fresh,mut bmax,mut omax)=(0,0,0usize,0usize);for base in &bases{let i=owner_index(base,12);let(s,f)=owners[i].snapshot_pair(base);if let(Some(s),Some(f))=(s,f){paired+=1;bmax=bmax.max(f.bids.len().max(f.asks.len()));omax=omax.max(s.bids.len().max(s.asks.len()));if now>=s.received_ns&&now-s.received_ns<=800_000_000&&now>=f.received_ns&&now-f.received_ns<=800_000_000{fresh+=1}}}println!("{}",json!({"r10_depth_owner_live":errors==0&&paired==bases.len(),"requested":bases.len(),"binance_seen":sb.len(),"okx_seen":so.len(),"paired":paired,"fresh_final":fresh,"binance_max_levels":bmax,"okx_max_levels":omax,"updates_accepted":h.n,"errors":errors,"trading":false}));}